begin;
create extension if not exists pgtap with schema extensions;
select plan(46);
insert into public.companies(id,slug,name) values ('10000000-0000-0000-0000-000000000099','work-isolated','Test');
insert into public.work_cards(company_id,stage_id,title) select company_id,id,'Private' from public.work_stages where company_id='10000000-0000-0000-0000-000000000099' and position=1;
insert into public.work_creatives(company_id,card_id,name) select company_id,id,'Private' from public.work_cards where company_id='10000000-0000-0000-0000-000000000099';
insert into storage.objects(bucket_id,name) values ('creatives','10000000-0000-0000-0000-000000000099/private.png');
select is((select count(*)::int from public.work_stages where company_id='10000000-0000-0000-0000-000000000099'),9,'new company receives nine stages');
select is((select count(*)::int from public.work_labels where company_id='10000000-0000-0000-0000-000000000099'),8,'new company receives labels');
update public.work_stages set position=1 where company_id='10000000-0000-0000-0000-000000000001' and kind='after_review';
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select is((select count(*)::int from public.work_stages where company_id='10000000-0000-0000-0000-000000000099'),0,'stages isolated');
select is((select count(*)::int from public.work_labels where company_id='10000000-0000-0000-0000-000000000099'),0,'labels isolated');
select is((select count(*)::int from public.work_cards where company_id='10000000-0000-0000-0000-000000000099'),0,'cards isolated');
select is((select count(*)::int from public.work_activity where company_id='10000000-0000-0000-0000-000000000099'),0,'activity isolated');
select is((select count(*)::int from public.work_creatives where company_id='10000000-0000-0000-0000-000000000099'),0,'creatives isolated');
select is((select count(*)::int from storage.objects where bucket_id='creatives' and name like '10000000-0000-0000-0000-000000000099/%'),0,'storage select isolated');
select throws_ok($$insert into storage.objects(bucket_id,name) values ('creatives','10000000-0000-0000-0000-000000000099/forbidden.png')$$,'42501',null,'storage insert isolated');
select throws_ok($$update public.work_cards set stage_id=(select id from public.work_stages where company_id='10000000-0000-0000-0000-000000000001' and kind='after_review' limit 1) where id=1$$,'P0001','contributors cannot move beyond review','contributor cannot approve after reordering');
select throws_ok($$update public.work_cards set stage_id=(select id from public.work_stages where company_id='10000000-0000-0000-0000-000000000001' and name='معتمد') where id=1$$,'P0001','contributors cannot move beyond review','contributor cannot enter معتمد');
select throws_ok($$update public.work_cards set stage_id=(select id from public.work_stages where company_id='10000000-0000-0000-0000-000000000001' and name='مجدول للنشر') where id=1$$,'P0001','contributors cannot move beyond review','contributor cannot enter مجدول للنشر');
select throws_ok($$update public.work_cards set stage_id=(select id from public.work_stages where company_id='10000000-0000-0000-0000-000000000001' and name='منشور') where id=1$$,'P0001','contributors cannot move beyond review','contributor cannot enter منشور');
select throws_ok($$update public.work_cards set stage_id=(select id from public.work_stages where company_id='10000000-0000-0000-0000-000000000001' and name='إعلانات شغالة') where id=1$$,'P0001','contributors cannot move beyond review','contributor cannot enter إعلانات شغالة');
select lives_ok($$select public.move_work_card('10000000-0000-0000-0000-000000000001',1,(select id from public.work_stages where company_id='10000000-0000-0000-0000-000000000001' and kind='review'),'https://example.test/stage')$$,'move with evidence');
select lives_ok($$select public.edit_work_card('10000000-0000-0000-0000-000000000001',1,'{"offering":"Test offering","caption":"Test caption"}','https://example.test/edit')$$,'edit brief and caption');
select throws_ok($$select public.change_work_card('10000000-0000-0000-0000-000000000001',1,'actor','{"person":"30000000-0000-0000-0000-000000000002"}','https://example.test/actor')$$,'P0001','current approver controls next actor','review step controls next actor');
select lives_ok($$select public.change_work_card('10000000-0000-0000-0000-000000000001',1,'assignee','{"person":"30000000-0000-0000-0000-000000000002"}','https://example.test/assignee')$$,'assign member');
select lives_ok($$insert into public.work_checklist(company_id,card_id,title) values ('10000000-0000-0000-0000-000000000001',1,'Test item')$$,'create checklist item');
select lives_ok($$select public.change_work_card('10000000-0000-0000-0000-000000000001',1,'check',jsonb_build_object('item',(select id from public.work_checklist where card_id=1 and title='Test item'),'done',true),'https://example.test/check')$$,'check item');
select lives_ok($$select public.change_work_card('10000000-0000-0000-0000-000000000001',1,'comment','{"body":"Evidence comment"}','https://example.test/comment')$$,'add comment');
select lives_ok($$select public.change_work_card('10000000-0000-0000-0000-000000000001',1,'creative','{"name":"test.png"}')$$,'add creative');
select lives_ok($$select public.change_work_card('10000000-0000-0000-0000-000000000001',1,'version',jsonb_build_object('creative',(select id from public.work_creatives where card_id=1 and name='test.png'),'path','10000000-0000-0000-0000-000000000001/1/test.png'),'https://example.test/version')$$,'add version');
select lives_ok($$select public.change_work_card('10000000-0000-0000-0000-000000000001',1,'creative_with_version','{"name":"تصميم.png","path":"10000000-0000-0000-0000-000000000001/1/opaque"}')$$,'create creative and first version together');
select is((select count(*)::int from public.work_versions v join public.work_creatives c on c.id=v.creative_id where c.name='تصميم.png' and v.path='10000000-0000-0000-0000-000000000001/1/opaque'),1,'first version belongs to the named creative');
select throws_ok($$select public.change_work_card('10000000-0000-0000-0000-000000000001',1,'creative_with_version','{"name":"invalid.png","path":"wrong/path"}')$$,'23514',null,'invalid first version rejects the whole operation');
select is((select count(*)::int from public.work_creatives where card_id=1 and name='invalid.png'),0,'failed first version leaves no empty creative');
select is((select count(distinct details->>'field')::int from public.work_activity where card_id=1 and actor_id=auth.uid() and created_at is not null and ((details->>'field'='stage_id' and evidence='https://example.test/stage') or (details->>'field' in ('offering','caption') and evidence='https://example.test/edit') or (details->>'field'='next_actor' and evidence='https://example.test/actor'))),3,'stage brief and caption audited with actor time and evidence');
select is((select count(distinct action)::int from public.work_activity where card_id=1 and actor_id=auth.uid() and created_at is not null and ((action='assignee_changed' and evidence='https://example.test/assignee') or (action='checklist_changed' and evidence='https://example.test/check') or (action='comment_added' and evidence='https://example.test/comment') or (action='version_added' and evidence='https://example.test/version'))),4,'assignee checklist comment and version each audited with actor time and evidence');
select is((select body from public.work_comments where card_id=1 and body='Evidence comment'),'Evidence comment','comment body retained');
select is((select author_id from public.work_comments where card_id=1 and body='Evidence comment'),auth.uid(),'comment author recorded');
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000002',true);
with changed as (update public.work_comments set body='forged',author_id=auth.uid() where card_id=1 and body='Evidence comment' returning 1) select is((select count(*)::int from changed),0,'contributor cannot alter another member comment');
select is((select relrowsecurity from pg_class where oid='public.work_comments'::regclass),true,'comment row security is enabled');
select is((select rolsuper or rolbypassrls from pg_roles where rolname=current_user),false,'current role cannot bypass row security');
select isnt((select tableowner::text from pg_tables where schemaname='public' and tablename='work_comments'),current_user::text,'current role does not own the comment table');
select is((select count(*)::int from pg_policies where schemaname='public' and tablename='work_comments' and cmd in ('DELETE','ALL')),0,'no policy permits comment removal');
select is((select author_id from public.work_comments where card_id=1 and body='Evidence comment'),'30000000-0000-0000-0000-000000000001'::uuid,'original author survives attempted forgery');
select is((select details->>'body' from public.work_activity where card_id=1 and action='comment_added' and details->>'body'='Evidence comment'),'Evidence comment','activity keeps the original comment');
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select is((select count(*)::int from public.work_versions where company_id='10000000-0000-0000-0000-000000000099'),0,'versions isolated');
select is((select count(*)::int from public.work_assignees where company_id='10000000-0000-0000-0000-000000000099'),0,'assignees isolated');
select lives_ok($$update public.work_cards set go_live='2031-11-12 09:15:42.123+00' where id=1$$,'set date with seconds');
select lives_ok($$select public.edit_work_card('10000000-0000-0000-0000-000000000001',1,'{"offering":"Changed only","go_live":"2031-11-12T09:15"}','https://example.test/unchanged')$$,'save unchanged displayed minute');
select is((select go_live from public.work_cards where id=1),'2031-11-12 09:15:42.123+00'::timestamptz,'unchanged minute preserves seconds');
select is((select count(*)::int from public.work_activity where card_id=1 and details->>'field'='go_live' and evidence='https://example.test/unchanged'),0,'unmodified date creates no activity');
select lives_ok($$select public.edit_work_card('10000000-0000-0000-0000-000000000001',1,'{"go_live":"2031-11-12T09:16"}','https://example.test/changed')$$,'change displayed minute');
select is((select count(*)::int from public.work_activity where card_id=1 and details->>'field'='go_live' and evidence='https://example.test/changed'),1,'changed date creates activity');
select * from finish();
rollback;
